def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is not None:
            idents = pre.split('.')
        else:
            idents = None
        return (major, minor, patch, idents)

    def ident_key(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def cmp_key(v):
        major, minor, patch, idents = parse(v)
        if idents is None:
            pre_flag = 1
            pre_list = []
        else:
            pre_flag = 0
            pre_list = [ident_key(i) for i in idents]
        return (major, minor, patch, pre_flag, pre_list, len(pre_list))

    import functools

    def compare(a, b):
        ka = cmp_key(a)
        kb = cmp_key(b)
        # compare major, minor, patch, pre_flag
        if ka[0] != kb[0]:
            return -1 if ka[0] < kb[0] else 1
        if ka[1] != kb[1]:
            return -1 if ka[1] < kb[1] else 1
        if ka[2] != kb[2]:
            return -1 if ka[2] < kb[2] else 1
        if ka[3] != kb[3]:
            return -1 if ka[3] < kb[3] else 1
        # compare pre_list element-wise
        pa, pb = ka[4], kb[4]
        for x, y in zip(pa, pb):
            if x != y:
                return -1 if x < y else 1
        if len(pa) != len(pb):
            return -1 if len(pa) < len(pb) else 1
        return 0

    indexed = list(enumerate(versions))
    indexed.sort(key=functools.cmp_to_key(lambda a, b: compare(a[1], b[1]) or (a[0]-b[0])))
    return [v for i, v in indexed]

